// ── Prepare Crunchbase ────────────────────────────────────────────────────
// Runs once per company row. Builds the Anthropic request body for the funding
// / investor research call. Accepts scored-pipeline headers (company_name,
// full_name, company_website, state) or Salesforce-style ones (Account Name,
// Website, BillingState) as a fallback.
// Code node mode: "Run Once for Each Item".

const MODEL = "claude-haiku-4-5-20251001";

const c = $input.item.json;
const company = String(c["company_name"] || c["Account Name"] || c["Name"] || "").trim();
const name    = String(c["full_name"] || c["Full Name"] || "").trim();
const website = String(c["company_website"] || c["Website"] || "").trim();
const state   = String(c["state"] || c["Billing State/Province"] || c["BillingState"] || "").trim();

const prompt = `You are a B2B research assistant. Search Crunchbase, LinkedIn, and the web for funding and investor data on this company.

COMPANY: ${company}
PERSON:  ${name}
WEBSITE: ${website || "unknown"}
STATE:   ${state || "US"}

Search for:
1. Crunchbase page: crunchbase.com/organization/[company-slug]
2. Recent news about funding rounds
3. LinkedIn company page for employee count
4. Any PE/VC investor mentions

Return ONLY a valid JSON object — no markdown, no explanation:
{
  "founded_year": "<4-digit year or empty string>",
  "total_funding": "<e.g. $4.2M | $50M | $1.2B | Undisclosed | Unknown>",
  "last_funding_stage": "<Pre-Seed | Seed | Series A | Series B | Series C | Series D+ | PE Buyout | Growth Equity | Bootstrapped | Public | Unknown>",
  "last_funding_amount": "<e.g. $8M | $45M | Undisclosed | Unknown>",
  "last_funding_date": "<e.g. 2023-Q2 | 2024-01 | Unknown>",
  "employee_count": "<e.g. 12 | 85 | 200-500 | 1200 | Unknown>",
  "investors": "<comma-separated list of investor firm names — include PE firms, VC funds, angels. Empty string if none found>",
  "investor_types": "<comma-separated types matching investors list order: PE | VC | Angel | CVC | Family Office | Unknown>",
  "crunchbase_url": "<https://www.crunchbase.com/organization/[slug] or empty string>",
  "company_description": "<one sentence description of what the company does>",
  "is_pe_backed": "<Yes | No | Unknown>",
  "is_vc_backed": "<Yes | No | Unknown>"
}

Rules:
- Only include investors you confirmed via search — do NOT fabricate names
- If a field cannot be confirmed, use empty string "" or "Unknown"
- For investors, list all you can find — this is important`;

const cbBody = {
  model: MODEL,
  max_tokens: 1200,
  tools: [{ type: "web_search_20250305", name: "web_search" }],
  messages: [{ role: "user", content: prompt }],
};

return {
  json: {
    ...c,
    _company: company,
    _name: name,
    _website: website,
    _state: state,
    _cbBody: cbBody,
  },
};

// ── Merge Crunchbase ──────────────────────────────────────────────────────
// Parses the Claude funding/investor JSON and appends it as separate columns
// onto the original company row. Does NOT touch any hiring columns.
// Code node mode: "Run Once for Each Item".

function nodeJson(name) {
  try { return $(name).item.json; } catch (e) { return null; }
}

const company = $("Prepare Crunchbase").item.json;

// Defaults mirror enrich_crunchbase.py (is_*_backed default to "Unknown").
const funding = {
  founded_year: "",
  total_funding: "",
  last_funding_stage: "",
  last_funding_amount: "",
  last_funding_date: "",
  employee_count: "",
  investors: "",
  investor_types: "",
  crunchbase_url: "",
  company_description: "",
  is_pe_backed: "Unknown",
  is_vc_backed: "Unknown",
  _cb_status: "error",
  _cb_error: "",
};

try {
  const resp = nodeJson("Crunchbase Research");
  if (resp && resp.error) {
    funding._cb_error = String(resp.error.message || resp.error).slice(0, 200);
  } else if (resp && Array.isArray(resp.content)) {
    const text = resp.content
      .filter((b) => b && b.type === "text" && b.text)
      .map((b) => b.text)
      .join(" ");
    const m = text.match(/\{[\s\S]*?\}/);
    if (!m) throw new Error("No JSON in response");
    const d = JSON.parse(m[0]);
    const clean = (k, def = "") => String(d[k] != null ? d[k] : def).trim();

    funding.founded_year = clean("founded_year");
    funding.total_funding = clean("total_funding");
    funding.last_funding_stage = clean("last_funding_stage");
    funding.last_funding_amount = clean("last_funding_amount");
    funding.last_funding_date = clean("last_funding_date");
    funding.employee_count = clean("employee_count");
    funding.investors = clean("investors");
    funding.investor_types = clean("investor_types");
    funding.crunchbase_url = clean("crunchbase_url");
    funding.company_description = clean("company_description");
    funding.is_pe_backed = clean("is_pe_backed", "Unknown");
    funding.is_vc_backed = clean("is_vc_backed", "Unknown");
    funding._cb_status = "done";
    funding._cb_error = "";
  } else {
    funding._cb_error = "No response from Claude node";
  }
} catch (e) {
  funding._cb_error = String(e.message || e).slice(0, 200);
}

// Keep original row columns (minus internal _-prefixed helpers), then append funding.
const base = {};
for (const [k, v] of Object.entries(company)) {
  if (!k.startsWith("_")) base[k] = v;
}

return { json: { ...base, ...funding } };

// ── Map to Salesforce (Crunchbase) ────────────────────────────────────────
// Maps the funding enrichment output onto Account fields and diffs against
// the values read from Salesforce, so the PATCH body contains nothing but the
// fields that actually changed. Empty/unparseable enrichment values are
// skipped — they never blank out an existing Salesforce value.
//
// Eligibility gate: field PATCHes only run when _cb_status === "done" AND at
// least one confirmed field is present (crunchbase_url, parseable money/date,
// investors, usable stage, or employee count). Failed/empty research never
// writes the skip-proxy fields (Crunchbase_URL__c / Investors__c /
// crunchbase__Total_Funding_USD__c / stage / Latest_Funding_Date__c).
//
// Crunchbase managed-package fields (typed, so values are converted):
//
//   crunchbase__Latest_Round_Funding_Type__c        ← last_funding_stage
//   crunchbase__Latest_Round_Money_Raised_in_USD__c ← last_funding_amount
//   crunchbase__Total_Funding_USD__c                ← total_funding
//   crunchbase__Latest_Round_Date__c                ← last_funding_date
//   crunchbase__Number_of_Employees_Crunchbase__c   ← employee_count
//   crunchbase__Number_of_Investors__c              ← investors (count)
//
// Org custom fields:
//
//   Investors__c             ← investors
//   Crunchbase_URL__c        ← crunchbase_url
//   Latest_Funding_Amount__c ← last_funding_amount (parsed number)
//   Latest_Funding_Date__c   ← last_funding_date (YYYY-MM-DD)
//   Is_PE_Backed__c / Is_VC_Backed__c ← Yes/No/Unknown (or Checkbox)
//
// Skip proxy (SOQL / Skip Enriched): Account is treated as already enriched
// when ANY of Crunchbase_URL__c, Investors__c, crunchbase__Total_Funding_USD__c,
// crunchbase__Latest_Round_Funding_Type__c, Latest_Funding_Date__c is set.
//
// Description: enrichment blobs are NOT written. On an eligible run, any legacy
// automation block ("Funding:…[Funding enriched …]") is stripped.
// Company "About" is omitted (no Company_Description__c in this org).
// Code node mode: "Run Once for Each Item".

// Set true if Is_PE_Backed__c / Is_VC_Backed__c are Checkbox fields:
// Yes → true, No → false, Unknown → skipped.
const CHECKBOX_PE_VC = false;

const j = $input.item.json;
const changes = {};
const str = (v) => String(v == null ? "" : v).trim();

function setIfChanged(field, value) {
  if (value == null || value === "") return;
  const current = j[field];
  if (typeof value === "number") {
    const cur = current == null || current === "" ? null : Number(current);
    if (cur !== value) changes[field] = value;
  } else if (typeof value === "boolean") {
    if (Boolean(current) !== value) changes[field] = value;
  } else if (str(current) !== str(value)) {
    changes[field] = str(value);
  }
}

function yesNoToBool(v) {
  const s = str(v).toLowerCase();
  return s === "yes" ? true : s === "no" ? false : null;
}

function parseMoney(v) {
  const m = str(v).replace(/,/g, "").match(/^\$?\s*(\d+(?:\.\d+)?)\s*([KMB])?$/i);
  if (!m) return null;
  const mult = { K: 1e3, M: 1e6, B: 1e9 }[(m[2] || "").toUpperCase()] || 1;
  return Math.round(parseFloat(m[1]) * mult);
}

function parseDate(v) {
  const s = str(v);
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  if (/^\d{4}-\d{2}$/.test(s)) return `${s}-01`;
  const q = s.match(/^(\d{4})-Q([1-4])$/i);
  if (q) return `${q[1]}-${String((parseInt(q[2], 10) - 1) * 3 + 1).padStart(2, "0")}-01`;
  if (/^\d{4}$/.test(s)) return `${s}-01-01`;
  return null;
}

function parseEmployees(v) {
  const ec = str(v).replace(/,/g, "");
  if (/^\d+$/.test(ec)) return parseInt(ec, 10);
  const range = ec.match(/^(\d+)\s*[-–]\s*(\d+)$/);
  if (range) return Math.round((parseInt(range[1], 10) + parseInt(range[2], 10)) / 2);
  return null;
}

const cbStatus = str(j._cb_status);
const cbError = str(j._cb_error);
const stage = str(j.last_funding_stage);
const investors = str(j.investors);
const crunchbaseUrl = str(j.crunchbase_url);
const totalMoney = parseMoney(j.total_funding);
const lastMoney = parseMoney(j.last_funding_amount);
const lastDate = parseDate(j.last_funding_date);
const employees = parseEmployees(j.employee_count);
const usableStage = Boolean(stage && stage !== "Unknown");
const total = str(j.total_funding);

const confirmedBits = [];
if (crunchbaseUrl) confirmedBits.push("crunchbase_url");
if (totalMoney != null) confirmedBits.push("total_funding");
if (lastMoney != null) confirmedBits.push("last_funding_amount");
if (lastDate) confirmedBits.push("last_funding_date");
if (investors) confirmedBits.push("investors");
if (usableStage) confirmedBits.push("last_funding_stage");
if (employees !== null) confirmedBits.push("employee_count");

const researchOk = cbStatus === "done";
const hasConfirmed = confirmedBits.length > 0;
const eligible = researchOk && hasConfirmed;

let skipReason = "";
if (!researchOk) {
  skipReason = cbError || `research status=${cbStatus || "missing"}`;
} else if (!hasConfirmed) {
  skipReason = "no confirmed funding fields (url/money/date/investors/stage/employees)";
}

if (!eligible) {
  return {
    json: {
      Id: j.Id,
      Name: j.Name,
      Website: j.Website,
      _changes: {},
      _changedFields: "",
      _hasChanges: false,
      _eligible: false,
      _skipReason: skipReason,
      _cb_status: cbStatus || "error",
      _cb_error: cbError,
      _confirmedFields: "",
      total_funding: total,
      last_funding_stage: stage,
      last_funding_amount: str(j.last_funding_amount),
      investors,
      crunchbase_url: crunchbaseUrl,
    },
  };
}

// ── Crunchbase managed-package fields ─────────────────────────────────────
if (usableStage) setIfChanged("crunchbase__Latest_Round_Funding_Type__c", stage);
setIfChanged("crunchbase__Latest_Round_Money_Raised_in_USD__c", lastMoney);
setIfChanged("crunchbase__Total_Funding_USD__c", totalMoney);
setIfChanged("crunchbase__Latest_Round_Date__c", lastDate);

const investorCount = investors ? investors.split(",").filter((s) => s.trim()).length : null;
if (investorCount) setIfChanged("crunchbase__Number_of_Investors__c", investorCount);

// ── Org custom fields (skip proxies among these) ──────────────────────────
setIfChanged("Investors__c", investors);
setIfChanged("Crunchbase_URL__c", crunchbaseUrl);
setIfChanged("Latest_Funding_Amount__c", lastMoney);
setIfChanged("Latest_Funding_Date__c", lastDate);
if (CHECKBOX_PE_VC) {
  setIfChanged("Is_PE_Backed__c", yesNoToBool(j.is_pe_backed));
  setIfChanged("Is_VC_Backed__c", yesNoToBool(j.is_vc_backed));
} else {
  setIfChanged("Is_PE_Backed__c", str(j.is_pe_backed));
  setIfChanged("Is_VC_Backed__c", str(j.is_vc_backed));
}

if (employees !== null) {
  setIfChanged("NumberOfEmployees", employees);
  setIfChanged("crunchbase__Number_of_Employees_Crunchbase__c", employees);
}

// ── Description cleanup only (no new enrichment text) ─────────────────────
const current = str(j.Description);
const cleaned = current
  .replace(/(^|\n)Funding:[\s\S]*?\[Funding enriched \d{4}-\d{2}-\d{2}\]/g, "$1")
  .replace(/\n{3,}/g, "\n\n")
  .trim();
if (cleaned !== current) changes.Description = cleaned;

return {
  json: {
    Id: j.Id,
    Name: j.Name,
    Website: j.Website,
    _changes: changes,
    _changedFields: Object.keys(changes).sort().join(", "),
    _hasChanges: Object.keys(changes).length > 0,
    _eligible: true,
    _skipReason: "",
    _cb_status: "done",
    _cb_error: "",
    _confirmedFields: confirmedBits.join(", "),
    total_funding: total,
    last_funding_stage: stage,
    last_funding_amount: str(j.last_funding_amount),
    investors,
    crunchbase_url: crunchbaseUrl,
  },
};

// ── Build Run Summary Email ───────────────────────────────────────────────
// Connected from Map to Salesforce (after the Has Changes → Update Account
// branch in connection order) so PATCHes finish first under executionOrder v1.
// Lists enriched companies, skips, and failed PATCH bodies.
// Code node mode: "Run Once for All Items".

function safeAll(name) {
  try {
    return $(name).all().map((i) => i.json);
  } catch (e) {
    return [];
  }
}

const mapped = safeAll("Map to Salesforce");
const patched = safeAll("Update Account");

const attempted = mapped.filter((m) => m._eligible && m._hasChanges);
const skipped = mapped.filter((m) => !m._eligible);
const noOp = mapped.filter((m) => m._eligible && !m._hasChanges);

// Has Changes → Update Account preserves item order; pair by index.
const patchFailures = [];
const enrichedList = [];
for (let i = 0; i < attempted.length; i++) {
  const m = attempted[i];
  const p = patched[i];
  if (p && p.error) {
    const msg = String(
      (p.error.message || p.error.description || p.error) || "PATCH failed"
    ).slice(0, 300);
    patchFailures.push({
      name: m.Name || "?",
      id: m.Id || "",
      message: msg,
      body: JSON.stringify(m._changes || {}).slice(0, 400),
    });
  } else {
    enrichedList.push(m);
  }
}

const lines = [];
lines.push("Hi team,");
lines.push("");
lines.push("Weekly Salesforce Account Crunchbase enrichment summary:");
lines.push("");
lines.push(`  • Researched:  ${mapped.length}`);
lines.push(`  • Enriched:    ${enrichedList.length}`);
lines.push(`  • Unchanged:   ${noOp.length} (eligible, Salesforce already matched)`);
lines.push(`  • Skipped:     ${skipped.length} (ineligible — will retry next week)`);
lines.push(`  • PATCH fail:  ${patchFailures.length}`);
lines.push("");

if (enrichedList.length) {
  lines.push("── Companies enriched ──");
  for (const m of enrichedList) {
    const bits = [
      m.last_funding_stage,
      m.total_funding,
      m.investors ? `investors: ${m.investors}` : "",
    ]
      .filter(Boolean)
      .join(" | ");
    lines.push(
      `- ${m.Name || "?"} (${m.Id || "no Id"})${bits ? ` — ${bits}` : ""}` +
        (m.crunchbase_url ? ` — ${m.crunchbase_url}` : "")
    );
    if (m._changedFields) lines.push(`    fields: ${m._changedFields}`);
  }
  lines.push("");
}

if (skipped.length) {
  lines.push("── Skipped (marker NOT written; will retry) ──");
  for (const m of skipped) {
    lines.push(
      `- ${m.Name || "?"} (${m.Id || "no Id"}): ${m._skipReason || m._cb_error || "ineligible"}`
    );
  }
  lines.push("");
}

if (patchFailures.length) {
  lines.push("── PATCH failures ──");
  for (const f of patchFailures) {
    lines.push(`- ${f.name} (${f.id}): ${f.message}`);
    if (f.body) lines.push(`    body: ${f.body}`);
  }
  lines.push("");
}

if (noOp.length) {
  lines.push(`── Eligible but unchanged (${noOp.length}) ──`);
  for (const m of noOp) {
    lines.push(`- ${m.Name || "?"} (${m.Id || "no Id"})`);
  }
  lines.push("");
}

lines.push("— Automations (n8n)");

const hasProblems = skipped.length > 0 || patchFailures.length > 0;
const subject = hasProblems
  ? `⚠️ Crunchbase Account enrichment — ${enrichedList.length} enriched, ${skipped.length} skipped, ${patchFailures.length} PATCH fail`
  : `✅ Crunchbase Account enrichment — ${enrichedList.length} companies enriched`;

return [
  {
    json: {
      subject,
      body: lines.join("\n"),
      hasAttachment: false,
      outcome: hasProblems ? "partial" : "success",
      enrichedCount: enrichedList.length,
      skippedCount: skipped.length,
      patchFailCount: patchFailures.length,
      researchedCount: mapped.length,
    },
  },
];

// ── Build Failure Email ───────────────────────────────────────────────────
// Fires only when the workflow HARD-fails, via the Error Trigger. Produces the
// failure subject/body for the shared Send Email node. No attachment.
// Code node mode: "Run Once for All Items".

const info = ($input.first() && $input.first().json) || {};
const wf =
  (info.workflow && info.workflow.name) ||
  "Salesforce Account Enrichment (Crunchbase funding, weekly)";
const exec = info.execution || {};
const errMsg =
  (exec.error && (exec.error.message || exec.error)) || "Unknown error";
const lastNode = exec.lastNodeExecuted || "unknown node";
const url = exec.url || "";

const subject = `⚠️ Crunchbase Account enrichment FAILED — ${wf}`;

const parts = [
  "Hi team,",
  "",
  "The weekly Salesforce Crunchbase enrichment run did NOT complete.",
  "Accounts researched in a partial run (if any) were not summarised by the success email.",
  "",
  `  • Workflow:  ${wf}`,
  `  • Failed at: ${lastNode}`,
  `  • Error:     ${String(errMsg).slice(0, 300)}`,
];
if (url) parts.push(`  • Execution: ${url}`);
parts.push("");
parts.push(
  "Check n8n Executions, Anthropic quota, and the Salesforce credential/host."
);
parts.push("Ineligible accounts are not marked enriched and will retry next week.");
parts.push("");
parts.push("— Automations (n8n)");

return [
  {
    json: {
      subject,
      body: parts.join("\n"),
      hasAttachment: false,
      outcome: "failure",
    },
  },
];
